#include "window.h"
QWidget *MainWindow::cpuPage(){
 auto *root=page("CPU · Monitor, núcleos e cálculos");auto *layout=qobject_cast<QVBoxLayout*>(root->layout());auto *grid=new QGridLayout;
 int i=0;for(auto entry:QList<QPair<QString,QString>>{{"cpuModel","Processador"},{"cpuUsage","Uso CPU"},{"cpuPhysicalCores","Núcleos físicos"},{"cpuLogicalProcessors","Processadores lógicos"},{"cpuTemp","Temperatura CPU"},{"systemRamTotal","Memória do sistema"}}){auto *card=new NeonCard(entry.second);auto *value=new QLabel("N/D");value->setWordWrap(true);value->setStyleSheet("font-size:20px;");card->body()->addWidget(value);cpuValues[entry.first]=value;grid->addWidget(card,i/3,i%3);++i;}layout->addLayout(grid);
 auto *cores=new QGroupBox("Processadores lógicos · cores acompanham a utilização");cpuCoresGrid=new QGridLayout(cores);layout->addWidget(cores);
 auto *bench=new QGroupBox("Benchmark CPU · C++ compartilhado com Windows");auto *controls=new QHBoxLayout(bench);cpuBenchMode=new QComboBox;cpuBenchMode->addItems({"Mistura de inteiros","FP64 · raiz e seno","Contagem de primos"});cpuBenchThreads=new QSpinBox;cpuBenchThreads->setRange(1,qMax(1,QThread::idealThreadCount()));cpuBenchThreads->setValue(qMax(1,QThread::idealThreadCount()));cpuBenchThreads->setSuffix(" threads");cpuBenchSeconds=new QSpinBox;cpuBenchSeconds->setRange(1,30);cpuBenchSeconds->setValue(3);cpuBenchSeconds->setSuffix(" s");cpuBenchStart=new QPushButton("Iniciar teste");auto *cancel=new QPushButton("Cancelar");controls->addWidget(cpuBenchMode);controls->addWidget(cpuBenchThreads);controls->addWidget(cpuBenchSeconds);controls->addWidget(cpuBenchStart);controls->addWidget(cancel);layout->addWidget(bench);
 cpuBenchResult=new QLabel("Nenhuma carga é executada automaticamente. Resultados são operações do algoritmo por segundo, não um score universal.");cpuBenchResult->setWordWrap(true);layout->addWidget(cpuBenchResult);
 connect(cpuBenchStart,&QPushButton::clicked,this,[this]{if(offline||testActive||cpuBenchProcess.state()!=QProcess::NotRunning)return;setTesting(true);cpuBenchOutput.clear();cpuBenchResult->setText("Teste em execução; acompanhe as cores dos processadores lógicos.");cpuBenchProcess.start(QCoreApplication::applicationDirPath()+"/gpu-cpu-worker",{QString::number(cpuBenchMode->currentIndex()),QString::number(cpuBenchThreads->value()),QString::number(cpuBenchSeconds->value()*1000)});});
 connect(cancel,&QPushButton::clicked,&cpuBenchProcess,&QProcess::kill);
 connect(&cpuBenchProcess,&QProcess::readyReadStandardOutput,this,[this]{cpuBenchOutput+=cpuBenchProcess.readAllStandardOutput();});
 connect(&cpuBenchProcess,qOverload<int,QProcess::ExitStatus>(&QProcess::finished),this,[this](int code,QProcess::ExitStatus status){setTesting(false);auto r=QJsonDocument::fromJson(cpuBenchOutput).object();if(code!=0||status!=QProcess::NormalExit||!r["valid"].toBool()){cpuBenchResult->setText("Teste interrompido ou inválido; nenhum resultado aprovado.");return;}r["cpuModel"]=latest["cpuModel"];r["timestamp"]=QDateTime::currentDateTimeUtc().toString(Qt::ISODateWithMs);QString error;saveJson(configRoot()+"/cpu-history/"+QUuid::createUuid().toString(QUuid::WithoutBraces)+".json",r,&error);cpuBenchResult->setText(QString("%1 threads · %2 s · %3 operações/s · checksum %4%5").arg(r["threads"].toInt()).arg(r["seconds"].toDouble(),0,'f',2).arg(r["operationsPerSecond"].toDouble(),0,'f',0).arg(r["checksum"].toDouble(),0,'g',6).arg(error.isEmpty()?" · resultado salvo":" · erro ao salvar: "+error));});
 connect(&cpuBenchProcess,&QProcess::errorOccurred,this,[this](QProcess::ProcessError e){if(e==QProcess::FailedToStart){setTesting(false);cpuBenchResult->setText(cpuBenchProcess.errorString());}});
 cpuBenchStart->setEnabled(!offline);layout->addStretch();return root;
}
void MainWindow::updateCpu(const QJsonObject &o){
 for(auto it=cpuValues.begin();it!=cpuValues.end();++it){const auto v=o[it.key()];QString text="N/D";if(v.isString())text=v.toString();if(v.isDouble())text=QString::number(v.toDouble(),'f',it.key()=="cpuUsage"?1:0);if(it.key()=="cpuUsage"&&v.isDouble())text+=" %";if(it.key()=="cpuTemp"&&v.isDouble())text+=" °C";if(it.key()=="systemRamTotal"&&v.isDouble())text=QString::number(v.toDouble()/1073741824.,'f',1)+" GiB";it.value()->setText(text);}
 const auto cores=o["cpuCores"].toArray();int col=0;for(auto item:cores){auto c=item.toObject();int id=c["id"].toInt();if(!cpuCoreCards.contains(id)){auto *card=new NeonCard(QString("CPU %1 · lógico").arg(id));card->setCompact(true);auto *value=new QLabel("N/D");value->setWordWrap(true);card->body()->addWidget(value);cpuCoreCards[id]=card;cpuCoreValues[id]=value;cpuCoresGrid->addWidget(card,col/4,col%4);}auto value=c["usage"];cpuCoreValues[id]->setText((value.isDouble()?QString::number(value.toDouble(),'f',1)+" %":"N/D")+(c["mhz"].isDouble()?QString(" · %1 MHz").arg(c["mhz"].toDouble(),0,'f',0):""));cpuCoreCards[id]->setReading(QJsonObject{{"cpuUsage",value}},"cpuUsage",QColor("#76b900"));++col;}
}
